package com.lbos.commercecustomer.client; import com.lbos.commercecustomer.dto.client.order.*;import java.util.UUID;import org.springframework.cloud.openfeign.FeignClient;import org.springframework.web.bind.annotation.*; @FeignClient(name="lbos-order", configuration = ServiceBasicAuthFeignConfig.class) public interface OrderLogisticsClient {@PostMapping("/api/v1/internal/delivery/serviceability-checks") ServiceabilityResponse serviceability(@RequestBody ServiceabilityRequest request);@GetMapping("/api/v1/internal/orders/{orderId}/review-eligibility") ReviewEligibilityResponse reviewEligibility(@PathVariable Long orderId,@RequestParam UUID customerProfileId,@RequestParam Long productId);@GetMapping("/api/v1/internal/orders/eligible-order-for-review") ReviewEligibilityResponse eligibleOrderForReview(@RequestParam UUID customerProfileId,@RequestParam Long productId);}